  `condition_note` varchar(500) DEFAULT NULL,
  `comment` text DEFAULT NULL,
  `photo_note` varchar(500) DEFAULT NULL,
  `repair_action` text DEFAULT NULL,
  `todo_done` tinyint(1) NOT NULL DEFAULT 0,
